 * Licensed under commercial license. See LICENSE.md in the package root for more information
 *-------------------------------------------------------------------------------------------
 */
"use client";
import { BrowserSupportService as t } from "./browser-support.service.mjs";
import { canUseDOM as o } from "./canUseDOM.mjs";
const s = () => !o || !document.body ? !1 : new t().scrollbarWidth, d = (r) => {
  if (!o || !document.body)
    return !1;
  const e = r || new t().scrollbarWidth;
  document.body.style.setProperty("--kendo-scrollbar-width", `${e}px`);
};
export {
  s as getScrollbarWidth,
  d as setScrollbarWidth
};
